package com.analyzercoder.interfaces.rest;
import com.analyzercoder.application.repository.RepositorySourceImportService;import com.analyzercoder.domain.repository.RepositorySourceType;import com.analyzercoder.infrastructure.repository.RemoteRepositoryTargetPolicy;import com.analyzercoder.security.SecurityContext;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/repository-imports") public class RepositorySourceImportController{private final RepositorySourceImportService service;public RepositorySourceImportController(RepositorySourceImportService service){this.service=service;}
@PostMapping("/remote")public RepositoryController.RepositoryResponse remote(@Valid@RequestBody RemoteInput in,HttpServletRequest request){SecurityContext.requireAdmin(request);RemoteRepositoryTargetPolicy.requireAllowed(in.url());return RepositoryController.RepositoryResponse.from(service.importRemote(in.name(),in.url(),in.branch(),in.sourceType()));}
@PostMapping(value="/zip",consumes="multipart/form-data")public RepositoryController.RepositoryResponse zip(@RequestParam String name,@RequestPart MultipartFile file,HttpServletRequest request){SecurityContext.requireAdmin(request);return RepositoryController.RepositoryResponse.from(service.importZip(name,file));}
public record RemoteInput(@NotBlank String name,@NotBlank String url,String branch,RepositorySourceType sourceType){}
}
